'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var Float64Array = require( '@stdlib/array/float64' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dorglq = require( './../lib/ndarray.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var opts = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {PositiveInteger} N - number of elements along each dimension
* @returns {Function} benchmark function
*/
function createBenchmark( order, N ) {
	var LWORK = N * 32; // workspace large enough for blocked code
	var WORK = new Float64Array( LWORK );
	var TAU = new Float64Array( N );
	var sc1;
	var sc2;
	var A;

	A = discreteUniform( N*N, 1.0, 10.0, opts );
	if ( isColumnMajor( order ) ) {
		sc1 = 1;
		sc2 = N;
	} else { // order === 'row-major'
		sc1 = N;
		sc2 = 1;
	}

	// Set the diagonal of A to 1.0 to ensure the matrix is well-formed
	A[ 0 ] = 1.0;
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var d;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			d = dorglq( N, N, N, A, sc1, sc2, 0, TAU, 1, 0, WORK, 1, 0, LWORK );
			if ( d < 0 ) {
				b.fail( 'should return a success status code' );
			}
		}
		b.toc();
		if ( d < 0 ) {
			b.fail( 'should return a success status code' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var min;
	var max;
	var ord;
	var N;
	var f;
	var i;
	var j;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( j = 0; j < LAYOUTS.length; j++ ) {
		ord = LAYOUTS[ j ];
		for ( i = min; i <= max; i++ ) {
			N = floor( pow( pow( 10, i ), 1.0/2.0 ) );
			f = createBenchmark( ord, N );
			bench( format( '%s::square_matrix:ndarray:order=%s,size=%d', pkg, ord, N*N ), f );
		}
	}
}

main();
